import { Box, Code, DocsSection, Header, type Section } from "react-lib-tools";
import { TypeFields } from "../TypeFields";

/** Generated by `compile:types` */
export type ModelTypeMetadata = {
  description: Section[];
  // Types combined with the type's own fields (e.g. "WorkspaceImperativeHandle" in "ParentWorkspace")
  extends?: string[];
  fields: {
    description: Section[];
    name: string;
    optional: boolean;
    type: string;
  }[];
  html?: string | undefined;
  name: string;
};

/**
 * Page documenting one of the types that make up a workspace's model.
 */
export function ModelType({ json }: { json: ModelTypeMetadata }) {
  return (
    <Box direction="column" gap={4}>
      <Header section="Model" title={json.name} />
      <DocsSection sections={json.description} />
      {json.html && <Code html={json.html} />}
      {json.fields.length > 0 && <TypeFields json={json} />}
    </Box>
  );
}
